import{_ as t,o as a,c as i,ah as s}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse('{"title":"School life","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/vie-scolaire/index.md","filePath":"src/en/guide/vie-scolaire/index.md"}'),r={name:"en/guide/vie-scolaire/index.md"};function o(n,e,c,d,l,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="school-life" tabindex="-1">School life <a class="header-anchor" href="#school-life" aria-label="Permalink to &quot;School life&quot;">​</a></h1><p>The school life team follows students&#39; daily life outside the classroom: attendance, discipline, cafeteria, transport and extracurricular activities. Some of these pages are also accessible to teachers or the registrar&#39;s office for viewing only; this guide describes the school life view, which has access to every action.</p><div class="info custom-block"><p class="custom-block-title">One site</p><p>If your employee profile names a site, ERA only shows you that site: students, classes, attendance, incidents, discipline councils, cafeteria, transport, activities and dashboard. A record from another site is neither listed nor opened. With no site on your profile, you see the whole school. The administrator sets the site on the <a href="/era-guide/en/guide/admin/personnel-utilisateurs.html#manage-staff-records-and-contracts">employee record</a>.</p></div><p>Attendance and absences are part of academic life. The other activities are separate modules of the licence: school life (discipline), school catering, school transport and extracurricular activities. Only the ones your school has licensed appear in your menu.</p><p>This guide covers four activities:</p><table tabindex="0"><thead><tr><th>Page</th><th>What you do there</th></tr></thead><tbody><tr><td><a href="/era-guide/en/guide/vie-scolaire/presences-et-absences.html">Attendance and absences</a></td><td>Take daily attendance for classes, review absence justifications submitted by families</td></tr><tr><td><a href="/era-guide/en/guide/vie-scolaire/discipline-et-conseils.html">Discipline and councils</a></td><td>Record a disciplinary incident, convene and decide a disciplinary council</td></tr><tr><td><a href="/era-guide/en/guide/vie-scolaire/cantine-et-transport.html">Cafeteria and transport</a></td><td>Manage cafeteria menus and attendance, assign students to transport routes and take their attendance</td></tr><tr><td><a href="/era-guide/en/guide/vie-scolaire/activites-extrascolaires.html">Extracurricular activities</a></td><td>Take attendance for extracurricular activity sessions</td></tr></tbody></table><p>For anything about your personal account (login, profile, security, notifications), common to every role, see <a href="/era-guide/en/guide/prise-en-main.html">Getting started</a>.</p>',7)])])}const f=t(r,[["render",o]]);export{p as __pageData,f as default};
